function convertToCommaified(text) {
  // Split the text by the semicolon delimiter
  const threads = text.split(';');

  // Trim whitespace from each thread and filter out any empty strings
  const cleanedThreads = threads.map(thread => thread.trim()).filter(thread => thread !== '');

  // Join the cleaned threads with a comma
  const commaifiedText = cleanedThreads.join(',');

  return commaifiedText;
}

